export const getExportMyAccountUrl = () => {
  return `/v1/me/export`;
};

/**
 * @summary Queue an account export
 */
export const exportMyAccount = async (
  createAccountExportRequest: CreateAccountExportRequest,
  options?: RequestInit,
): Promise<exportMyAccountResponse> => {
  const res = await fetch(getExportMyAccountUrl(), {
    ...options,
    method: "POST",
    headers: getHeaders({ "Content-Type": "application/json" }, options?.headers),
    body: JSON.stringify(createAccountExportRequest),
  });

  const body = [204, 205, 304].includes(res.status) ? null : await res.text();

  const data: exportMyAccountResponse["data"] = body ? JSON.parse(body) : {};
  return { data, status: res.status, headers: res.headers } as exportMyAccountResponse;
};

export const getExportMyAccountMutationKey = () => ["exportMyAccount"] as const;

export const getExportMyAccountMutationOptions = <
  TError = ProblemDetails,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof exportMyAccount>>,
    TError,
    ExportMyAccountMutationVariables,
    TContext
  >;
  fetch?: RequestInit;
}): UseMutationOptions<
  Awaited<ReturnType<typeof exportMyAccount>>,
  TError,
  ExportMyAccountMutationVariables,
  TContext
> => {
  const mutationKey = getExportMyAccountMutationKey();
  const { mutation: mutationOptions, fetch: fetchOptions } = options
    ? options.mutation && "mutationKey" in options.mutation && options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, fetch: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof exportMyAccount>>,
    ExportMyAccountMutationVariables
  > = (props) => {
    const { data } = props ?? {};

    return exportMyAccount(data, fetchOptions);
  };

  return { mutationFn, ...mutationOptions };
};

